import{_ as e,o as n,c as t,a6 as i}from"./chunks/framework.DycQjAfF.js";const r="/WareHouse/images/sop/contoh-grn.jpg",p=JSON.parse('{"title":"SOP Penerimaan Barang","description":"Langkah menerima material dari vendor, mulai dari cek dokumen dan inspeksi, penerbitan GRN, sampai barang tersimpan dan tercatat.","frontmatter":{"title":"SOP Penerimaan Barang","description":"Langkah menerima material dari vendor, mulai dari cek dokumen dan inspeksi, penerbitan GRN, sampai barang tersimpan dan tercatat.","status":"ditinjau","dasar":"Instruksi Kerja Penerimaan Material Gudang Teknik dan alur barang masuk Gudang Teknik","nomor_dokumen":null,"versi":0.3,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-22T00:00:00.000Z","kategori":"SOP","sumber":["ik-gudang-teknik","ppt-gudang-teknik","catatan-alur"],"kata_kunci":["SOP","penerimaan barang","receiving","barang masuk","vendor","good received","surat jalan","PO","purchase order","GRN","good received note","inspektor laboratorium","material reject","CAR","non stock item","klaim","kartu stok"]},"headers":[],"relativePath":"sop/penerimaan-barang.md","filePath":"sop/penerimaan-barang.md"}'),s={name:"sop/penerimaan-barang.md"};function l(d,a,o,u,k,m){return n(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="sop-penerimaan-barang" tabindex="-1">SOP Penerimaan Barang <a class="header-anchor" href="#sop-penerimaan-barang" aria-label="Permalink to &quot;SOP Penerimaan Barang&quot;">​</a></h1><p class="lead">Dipakai setiap kali vendor atau supplier mengantar material ke Gudang Teknik. Isinya diringkas dari Instruksi Kerja Penerimaan Material Gudang Teknik.</p><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><p>Memastikan setiap material yang datang ke PT Bakrie Pipe Industries sudah diperiksa dan memenuhi kriteria serta spesifikasi teknis yang diminta, sebelum disimpan dan dicatat.</p><h2 id="siapa-memeriksa-apa" tabindex="-1">Siapa memeriksa apa <a class="header-anchor" href="#siapa-memeriksa-apa" aria-label="Permalink to &quot;Siapa memeriksa apa&quot;">​</a></h2><p>Tidak semua material diperiksa oleh orang yang sama:</p><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Kelompok material</th><th>Diperiksa oleh</th></tr></thead><tbody><tr><td data-label="Kelompok material">ATK, consumable, dan material part</td><td data-label="Diperiksa oleh">Bagian penerimaan Gudang Teknik (Good Received)</td></tr><tr><td data-label="Kelompok material">Plastik transparan, dop plastic protector, dop end cup protector, dop metal protector, varnish, zinc ingot, cat meni, dan material coating</td><td data-label="Diperiksa oleh">Inspektor Laboratorium, sesuai instruksi kerja verifikasi pembelian WI.QP-07</td></tr><tr><td data-label="Kelompok material">Material non-stock item</td><td data-label="Diperiksa oleh">User yang memesan, paling lambat <strong>3 hari kerja</strong></td></tr></tbody></table><p>Material part yang perlu dicek dimensi dan kekerasannya, misalnya U-ring seal atau discutter, diperiksa oleh Maintenance CAD Center dan Inspektor Laboratorium, lengkap dengan laporan hasil pemeriksaannya.</p><h2 id="peran" tabindex="-1">Peran <a class="header-anchor" href="#peran" aria-label="Permalink to &quot;Peran&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Peran</th><th>Tanggung jawab</th></tr></thead><tbody><tr><td data-label="Peran"><strong>Supervisor Gudang</strong></td><td data-label="Tanggung jawab">Mengawasi kepatuhan terhadap instruksi kerja.</td></tr><tr><td data-label="Peran"><strong>Good Received</strong></td><td data-label="Tanggung jawab">Menerima dan mendokumentasikan kedatangan material, lalu meneruskan ketidaksesuaian ke buyer procurement/purchasing.</td></tr><tr><td data-label="Peran"><strong>Inspektor Laboratorium</strong></td><td data-label="Tanggung jawab">Memeriksa material kelompok laboratorium. Teknisi atau engineer laboratorium berhak menerbitkan Corrective Action Report (CAR) jika material tidak sesuai.</td></tr><tr><td data-label="Peran"><strong>User</strong></td><td data-label="Tanggung jawab">Memeriksa material non-stock item yang dipesannya.</td></tr></tbody></table><h2 id="yang-perlu-disiapkan" tabindex="-1">Yang perlu disiapkan <a class="header-anchor" href="#yang-perlu-disiapkan" aria-label="Permalink to &quot;Yang perlu disiapkan&quot;">​</a></h2><ul><li>Komputer, printer, dan akses ke sistem ERP.</li><li>Kamera saku untuk dokumentasi kedatangan barang.</li><li>Alat ukur: jangka sorong (<em>vernier caliper</em>), durometer, <em>stick sounding</em> untuk tangki atau drum, dan timbangan.</li><li>Alat bantu: troli, tangga portabel, dan forklift. Forklift hanya dioperasikan oleh orang yang berwenang.</li><li>Form ceklis penerimaan barang <strong>HSE-PP-K3L-01D</strong> (revisi terakhir).</li></ul><h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><ol><li><strong>Cek dokumen.</strong> Pastikan setiap kedatangan barang disertai surat jalan dan dokumen pendukung lainnya, misalnya PO (<em>purchase order</em>).</li><li><strong>Cocokkan barang dengan pesanan.</strong> Bandingkan barang dengan PO dan surat jalan. Kalau tidak sesuai, barang dikembalikan ke vendor.</li><li><strong>Bawa barang masuk</strong> ke area inspeksi, lalu terima barangnya.</li><li><strong>Periksa jumlah, kondisi, dan mutunya</strong> sesuai tabel di atas. <ul><li>ATK, consumable, dan material part langsung diperiksa bagian penerimaan, lalu form ceklis penerimaan barang diisi.</li><li>Material kelompok laboratorium diteruskan ke Inspektor Laboratorium.</li><li>Material non-stock item diteruskan ke user, yang lalu melengkapi administrasi pengebonan barang sementara.</li></ul></li><li><strong>Pastikan material memenuhi syarat</strong> visual, spesifikasi, mutu, dan jumlah. Kalau tidak, ikuti bagian <a href="#kalau-material-tidak-sesuai">Kalau material tidak sesuai</a>.</li><li><strong>Terbitkan Good Received Note (GRN)</strong>, yaitu laporan penerimaan material yang ditujukan kepada vendor. Lihat <a href="#contoh-grn">contohnya</a>.</li><li><strong>Input data penerimaan ke database</strong> sesuai alur sistem penerimaan barang dari tim IT: jumlah, jenis barang, tipe barang, dan tanggal masuk.</li><li><strong>Simpan barang</strong> di lokasi yang tercatat di database, sesuai <a href="./penyimpanan-barang">SOP Penyimpanan Barang</a>.</li><li><strong>Catat di kartu stok</strong> di rak tempat barang disimpan.</li></ol><div class="info custom-block"><p class="custom-block-title">STTB tidak dipakai lagi</p><p>Dulu penerimaan barang memakai Surat Tanda Terima Barang (STTB). Sekarang STTB sudah tidak digunakan, dan bukti penerimaan barang memakai <strong>GRN</strong>.</p></div><p>Nomor langkah di atas sama dengan nomor kotak di flowchart <a href="/WareHouse/alur-kerja/barang-masuk">Alur Barang Masuk</a>.</p><h2 id="contoh-grn" tabindex="-1">Contoh GRN <a class="header-anchor" href="#contoh-grn" aria-label="Permalink to &quot;Contoh GRN&quot;">​</a></h2><figure><p><img src="'+r+'" alt="Good Received Note nomor GRN/1026/255 untuk material RA3A00001 STEEL;STRAPPING;0.8x32mm;WITH;CERTIFICATE, diterima 6017 kg, diterima semua, mutu GOOD"></p><figcaption>Contoh GRN dari Gudang Teknik. Sebanyak 6.017 kg steel strapping diterima, semuanya lolos (tidak ada yang ditolak), dengan mutu baik.</figcaption></figure><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Bagian</th><th>Isinya</th></tr></thead><tbody><tr><td data-label="Bagian"><strong>Nomor GRN</strong></td><td data-label="Isinya">Contohnya <code>GRN/1026/255</code>. Angka <code>1026</code> tampaknya menunjukkan bulan dan tahun (Oktober 2026), sama seperti pada nomor reservasi <code>RSV/1026/…</code>.</td></tr><tr><td data-label="Bagian"><strong>To</strong></td><td data-label="Isinya">Nama dan alamat vendor yang mengirim barang.</td></tr><tr><td data-label="Bagian"><strong>Date</strong></td><td data-label="Isinya">Tanggal GRN diterbitkan.</td></tr><tr><td data-label="Bagian"><strong>PO Number dan PO Date</strong></td><td data-label="Isinya">Nomor dan tanggal PO yang dicocokkan dengan barang.</td></tr><tr><td data-label="Bagian"><strong>Prepared by dan Inspected by</strong></td><td data-label="Isinya">Petugas yang membuat GRN dan petugas yang memeriksa barang, lengkap dengan tanggal dan kode QR persetujuannya.</td></tr><tr><td data-label="Bagian"><strong>Material ID dan Material Name</strong></td><td data-label="Isinya">Nomor material dan deskripsinya, sesuai <a href="/WareHouse/divisi/kode-barang">standar cataloguing</a>. <code>RA3A00001</code> diawali <code>R</code>, artinya raw material atau material pendukung.</td></tr><tr><td data-label="Bagian"><strong>Uom</strong></td><td data-label="Isinya">Satuan barang, misalnya Kg.</td></tr><tr><td data-label="Bagian"><strong>Quantity: Received, Accepted, Rejected</strong></td><td data-label="Isinya">Jumlah yang datang, jumlah yang diterima karena sesuai, dan jumlah yang ditolak.</td></tr><tr><td data-label="Bagian"><strong>Quantity Info</strong></td><td data-label="Isinya">Keterangan jumlah, misalnya <em>SUFFICIENT</em> (cukup sesuai pesanan).</td></tr><tr><td data-label="Bagian"><strong>Quality Info</strong></td><td data-label="Isinya">Hasil pemeriksaan mutu, misalnya <em>GOOD</em>.</td></tr></tbody></table><h2 id="kalau-material-tidak-sesuai" tabindex="-1">Kalau material tidak sesuai <a class="header-anchor" href="#kalau-material-tidak-sesuai" aria-label="Permalink to &quot;Kalau material tidak sesuai&quot;">​</a></h2><ul><li>Barang yang tidak sesuai <strong>dipisahkan dan diberi tanda Material Reject</strong>.</li><li><strong>Stock item:</strong> Good Received memberi tahu buyer procurement/purchasing bahwa barang tidak sesuai spesifikasi permintaan pembelian dan akan dikembalikan.</li><li><strong>Material kelompok laboratorium:</strong> laboratorium membuat laporan ketidaksesuaian beserta hasil pemeriksaannya, dan bisa menerbitkan CAR.</li><li><strong>Non-stock item:</strong> user memberi tahu Good Received, lalu Good Received meneruskan proses klaim ke vendor melalui buyer procurement/purchasing.</li><li>Laporan ketidaksesuaian ditujukan ke departemen procurement/purchasing untuk disampaikan ke vendor.</li></ul><p>Kalau ragu apakah barang sesuai, jangan memutuskan sendiri. Tanyakan ke Good Received atau pembimbing.</p><h2 id="cek-sebelum-selesai" tabindex="-1">Cek sebelum selesai <a class="header-anchor" href="#cek-sebelum-selesai" aria-label="Permalink to &quot;Cek sebelum selesai&quot;">​</a></h2><ul class="daftar-periksa"><li>Surat jalan dan PO sudah dicek.</li><li>Barang sesuai pesanan, kondisinya baik, dan jumlahnya lengkap.</li><li>Material sudah diperiksa oleh pihak yang tepat (penerimaan, laboratorium, atau user).</li><li>GRN sudah terbit.</li><li>Data penerimaan sudah diinput ke database.</li><li>Barang ada di rak yang benar dan kartu stok sudah diisi.</li><li>Barang yang tidak sesuai sudah dipisahkan dan diberi tanda Material Reject.</li></ul><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Saat membongkar dan membawa barang</p><ul><li>Cek berat barang sebelum mengangkat. Minta bantuan atau pakai alat angkut untuk barang berat.</li><li>Alat angkut bermesin hanya boleh dipakai oleh orang yang berwenang.</li><li>Pakai sarung tangan saat membuka kemasan yang tajam atau diikat strapping.</li></ul></div><h2 id="acuan" tabindex="-1">Acuan <a class="header-anchor" href="#acuan" aria-label="Permalink to &quot;Acuan&quot;">​</a></h2><p>Instruksi kerja ini merujuk API Spec Q1, ISO 9001, QP-07, drawing Maintenance CAD Center, dan Technical Specification, masing-masing edisi atau revisi terakhir.</p>',28)])])}const b=e(s,[["render",l]]);export{p as __pageData,b as default};
